defmodule Elara.Tools do
  @moduledoc "Built-in tool implementations."

  alias Elara.Exec
  alias Elara.Tool.Ctx

  @spec read(map(), Ctx.t()) :: Elara.Tool.outcome()
  def read(%{"path" => path}, %Ctx{cwd: cwd}) when is_binary(path) do
    full = Path.expand(path, cwd)

    case File.read(full) do
      {:ok, content} -> {:ok, content}
      {:error, reason} -> {:error, "read failed: #{describe_posix(reason)} (#{path})"}
    end
  end

  def read(_args, _ctx), do: {:error, "read requires path"}

  @spec write(map(), Ctx.t()) :: Elara.Tool.outcome()
  def write(%{"path" => path, "content" => content}, %Ctx{cwd: cwd})
      when is_binary(path) and is_binary(content) do
    full = Path.expand(path, cwd)

    with :ok <- File.mkdir_p(Path.dirname(full)),
         :ok <- File.write(full, content) do
      {:ok, "wrote #{byte_size(content)} bytes to #{path}"}
    else
      {:error, reason} -> {:error, "write failed: #{describe_posix(reason)} (#{path})"}
    end
  end

  def write(_args, _ctx), do: {:error, "write requires path and content"}

  @spec edit(map(), Ctx.t()) :: Elara.Tool.outcome()
  def edit(%{"path" => path, "old_text" => old_text, "new_text" => new_text}, %Ctx{cwd: cwd})
      when is_binary(path) and is_binary(old_text) and is_binary(new_text) do
    full = Path.expand(path, cwd)

    case File.read(full) do
      {:ok, content} ->
        case :binary.matches(content, old_text) do
          [] ->
            {:error, "old_text not found in #{path}"}

          [_] ->
            updated = String.replace(content, old_text, new_text, global: false)

            case File.write(full, updated) do
              :ok -> {:ok, "edited #{path}"}
              {:error, reason} -> {:error, "edit write failed: #{describe_posix(reason)}"}
            end

          matches ->
            {:error, "old_text matched #{length(matches)} times in #{path}; need exactly one"}
        end

      {:error, reason} ->
        {:error, "edit read failed: #{describe_posix(reason)} (#{path})"}
    end
  end

  def edit(_args, _ctx), do: {:error, "edit requires path, old_text, and new_text"}

  @spec bash(map(), Ctx.t()) :: Elara.Tool.outcome()
  def bash(%{"command" => command}, %Ctx{} = ctx) when is_binary(command) do
    case Exec.run(["/bin/sh", "-c", command],
           cwd: ctx.cwd,
           max_bytes: ctx.max_output_bytes || 16_384,
           timeout_ms: ctx.timeout_ms || 30_000
         ) do
      {:ok, result} -> bash_result(result)
      {:error, {:not_started, message}} -> {:error, "execution failed: #{message}"}
      {:indeterminate, _message} = result -> result
    end
  end

  def bash(_args, _ctx), do: {:error, "bash requires command"}

  defp bash_result(%Exec.Result{termination: :exited, code: 0, output: output}),
    do: {:ok, output}

  defp bash_result(%Exec.Result{termination: :exited, code: code, output: output})
       when is_integer(code),
       do: {:error, "exit #{code}\n" <> output}

  defp bash_result(%Exec.Result{termination: :exited, signal: signal, output: output}),
    do: {:error, "signal #{signal}\n" <> output}

  defp bash_result(%Exec.Result{termination: :cancelled}), do: {:error, "cancelled"}
  defp bash_result(%Exec.Result{termination: :timed_out}), do: {:error, "timed out"}

  defp bash_result(%Exec.Result{termination: :truncated} = result) do
    {:error,
     "output truncated: bytes_total=#{result.bytes_total} bytes_sent=#{result.bytes_sent}\n" <>
       result.output}
  end

  defp describe_posix(:enoent), do: "no such file"
  defp describe_posix(:eacces), do: "permission denied"
  defp describe_posix(:eisdir), do: "is a directory"
  defp describe_posix(other), do: inspect(other)
end

defmodule Elara.Tool do
  @moduledoc "Tool values. run is MFA data, never a closure."

  defmodule PluginRef do
    @moduledoc false
    @type t :: %__MODULE__{
            id: String.t(),
            version: String.t(),
            generation: pos_integer(),
            server: pid()
          }
    defstruct [:id, :version, :generation, :server]
  end

  defmodule Ctx do
    @type t :: %__MODULE__{
            session_id: String.t() | nil,
            cwd: String.t(),
            plugin: PluginRef.t() | nil,
            tool_name: String.t() | nil,
            job_id: String.t() | nil,
            operation_digest: String.t() | nil,
            max_output_bytes: pos_integer() | nil,
            timeout_ms: pos_integer() | nil
          }
    defstruct [
      :session_id,
      :cwd,
      :plugin,
      :tool_name,
      :job_id,
      :operation_digest,
      :max_output_bytes,
      :timeout_ms
    ]
  end

  @type outcome :: {:ok, String.t()} | {:error, String.t()} | {:indeterminate, String.t()}

  @typedoc """
  parameters is a raw JSON Schema map, passed to the provider as is.
  run points at f(args :: map(), ctx :: Ctx.t()) :: outcome().
  """
  @type t :: %__MODULE__{
          name: String.t(),
          version: String.t(),
          description: String.t(),
          parameters: map(),
          run: {module(), atom()},
          plugin: PluginRef.t() | nil,
          capabilities: [String.t()],
          placement: :local | :remote | :any,
          mutating: boolean()
        }
  defstruct [
    :name,
    :description,
    :parameters,
    :run,
    :plugin,
    version: "1",
    capabilities: [],
    placement: :any,
    mutating: false
  ]

  @spec builtins() :: [t()]
  def builtins do
    [
      read_tool(),
      write_tool(),
      edit_tool(),
      bash_tool(),
      Elara.Skills.tool(),
      Elara.Threads.tool(),
      Elara.TestJobs.tool()
    ] ++ Elara.Threads.Communication.tools() ++ Elara.CheckDiagnosis.tools()
  end

  @doc false
  @spec builtin_write?(t()) :: boolean()
  def builtin_write?(%__MODULE__{} = tool) do
    tool.name == "write" and tool.version == "1" and tool.run == {Elara.Tools, :write} and
      tool.plugin == nil and tool.capabilities == ["filesystem:write"] and
      tool.placement == :any and tool.mutating
  end

  @doc "Table keyed by name. Duplicate names are an ArgumentError at session start."
  @spec table([t()]) :: %{String.t() => t()}
  def table(tools) when is_list(tools) do
    Enum.reduce(tools, %{}, fn
      %__MODULE__{name: name} = _tool, acc when is_map_key(acc, name) ->
        raise ArgumentError, "duplicate tool name: #{name}"

      %__MODULE__{name: name} = tool, acc ->
        Map.put(acc, name, tool)
    end)
  end

  defp read_tool do
    %__MODULE__{
      name: "read",
      description: "Read a file relative to the working directory.",
      parameters: %{
        "type" => "object",
        "properties" => %{
          "path" => %{"type" => "string", "description" => "Path to read"}
        },
        "required" => ["path"]
      },
      capabilities: ["filesystem:read"],
      run: {Elara.Tools, :read}
    }
  end

  defp write_tool do
    %__MODULE__{
      name: "write",
      description: "Write contents to a file, creating parent directories as needed.",
      parameters: %{
        "type" => "object",
        "properties" => %{
          "path" => %{"type" => "string", "description" => "Path to write"},
          "content" => %{"type" => "string", "description" => "File contents"}
        },
        "required" => ["path", "content"]
      },
      capabilities: ["filesystem:write"],
      mutating: true,
      run: {Elara.Tools, :write}
    }
  end

  defp edit_tool do
    %__MODULE__{
      name: "edit",
      description: "Replace exactly one occurrence of old_text with new_text in a file.",
      parameters: %{
        "type" => "object",
        "properties" => %{
          "path" => %{"type" => "string", "description" => "Path to edit"},
          "old_text" => %{"type" => "string", "description" => "Exact text to find once"},
          "new_text" => %{"type" => "string", "description" => "Replacement text"}
        },
        "required" => ["path", "old_text", "new_text"]
      },
      capabilities: ["filesystem:read", "filesystem:write"],
      mutating: true,
      run: {Elara.Tools, :edit}
    }
  end

  defp bash_tool do
    %__MODULE__{
      name: "bash",
      description: "Run a shell command in the working directory. stdout and stderr are merged.",
      parameters: %{
        "type" => "object",
        "properties" => %{
          "command" => %{"type" => "string", "description" => "Shell command to run"}
        },
        "required" => ["command"]
      },
      capabilities: ["shell"],
      mutating: true,
      run: {Elara.Tools, :bash}
    }
  end
end

